package com.mediconnect.dto;
import com.mediconnect.entity.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
public final class ApiDtos{private ApiDtos(){}
 public record UserView(Long _id,String name,String email,String role,String phone,LocalDate dateOfBirth,String gender,String address,String bloodGroup,String allergies,String emergencyContact,boolean isActive,boolean isApproved,String specialization,String qualification,Integer experience,BigDecimal consultationFee,String licenseNumber,LocalDateTime createdAt,Long hospitalId,String hospitalName,String hospitalSlug){public static UserView of(User u){return new UserView(u.getId(),u.getName(),u.getEmail(),u.getRole().name(),u.getPhone(),u.getDateOfBirth(),u.getGender(),u.getAddress(),u.getBloodGroup(),u.getAllergies(),u.getEmergencyContact(),u.isActive(),u.isApproved(),u.getSpecialization(),u.getQualification(),u.getExperience(),u.getConsultationFee(),u.getLicenseNumber(),u.getCreatedAt(),u.getHospital()==null?null:u.getHospital().getId(),u.getHospital()==null?null:u.getHospital().getName(),u.getHospital()==null?null:u.getHospital().getSlug());}}
 public record AuthResponse(String token,UserView user,boolean requiresApproval){}
 public record DepartmentView(Long _id,String name,String description,String location,String contactNumber,boolean isActive){public static DepartmentView of(Department d){return new DepartmentView(d.getId(),d.getName(),d.getDescription(),d.getLocation(),d.getContactNumber(),d.isActive());}}
 public record AppointmentView(Long _id,UserView patient,UserView doctor,Map<String,Object> department,LocalDate appointmentDate,LocalTime appointmentTime,String reason,String symptoms,String status,String consultationNotes,String cancellationReason,LocalDateTime createdAt){public static AppointmentView of(Appointment a){Map<String,Object> dep=a.getDepartment()==null?null:Map.of("_id",a.getDepartment().getId(),"name",a.getDepartment().getName());return new AppointmentView(a.getId(),UserView.of(a.getPatient()),UserView.of(a.getDoctor()),dep,a.getAppointmentDate(),a.getAppointmentTime(),a.getReason(),a.getSymptoms(),a.getStatus().name(),a.getConsultationNotes(),a.getCancellationReason(),a.getCreatedAt());}}
 public record AppointmentRescheduleView(Long id,Long appointmentId,Long actorId,String actorName,LocalDate oldDate,LocalTime oldTime,LocalDate newDate,LocalTime newTime,LocalDateTime createdAt){public static AppointmentRescheduleView of(AppointmentReschedule r){return new AppointmentRescheduleView(r.getId(),r.getAppointment().getId(),r.getActor().getId(),r.getActor().getName(),r.getOldDate(),r.getOldTime(),r.getNewDate(),r.getNewTime(),r.getCreatedAt());}}
 public record AvailabilityView(Long _id,Long doctor,LocalDate date,LocalTime startTime,LocalTime endTime,boolean isAvailable){public static AvailabilityView of(Availability a){return new AvailabilityView(a.getId(),a.getDoctor().getId(),a.getDate(),a.getStartTime(),a.getEndTime(),a.isAvailable());}}
 public record MedicalRecordView(Long _id,UserView patient,UserView doctor,Long appointmentId,String diagnosis,String notes,String vitals,LocalDateTime createdAt){public static MedicalRecordView of(MedicalRecord r){return new MedicalRecordView(r.getId(),UserView.of(r.getPatient()),UserView.of(r.getDoctor()),r.getAppointment()==null?null:r.getAppointment().getId(),r.getDiagnosis(),r.getNotes(),r.getVitals(),r.getCreatedAt());}}
 public record PrescriptionView(Long _id,UserView patient,UserView doctor,Long appointmentId,String medicine,String dosage,String frequency,String duration,String instructions,LocalDateTime createdAt){public static PrescriptionView of(Prescription p){return new PrescriptionView(p.getId(),UserView.of(p.getPatient()),UserView.of(p.getDoctor()),p.getAppointment()==null?null:p.getAppointment().getId(),p.getMedicine(),p.getDosage(),p.getFrequency(),p.getDuration(),p.getInstructions(),p.getCreatedAt());}}
 public record ReviewView(Long _id,UserView patient,UserView doctor,Long appointmentId,Integer rating,String comment,LocalDateTime createdAt){public static ReviewView of(Review r){return new ReviewView(r.getId(),UserView.of(r.getPatient()),UserView.of(r.getDoctor()),r.getAppointment().getId(),r.getRating(),r.getComment(),r.getCreatedAt());}}
 public record NotificationView(Long _id,String title,String message,String type,boolean read,LocalDateTime createdAt){public static NotificationView of(Notification n){return new NotificationView(n.getId(),n.getTitle(),n.getMessage(),n.getType(),n.isReadFlag(),n.getCreatedAt());}}
 public record AuditView(Long _id,UserView actor,String action,String targetType,Long targetId,String details,LocalDateTime createdAt){public static AuditView of(AuditLog a){return new AuditView(a.getId(),a.getActor()==null?null:UserView.of(a.getActor()),a.getAction(),a.getTargetType(),a.getTargetId(),a.getDetails(),a.getCreatedAt());}}
}
